class Codec:
    def serialize(self, root: 'TreeNode') -> str:
        tokens = []
        def visit(node):
            if node is None:
                tokens.append('#')
            else:
                tokens.append(str(node.val))
                visit(node.left)
                visit(node.right)
        visit(root)
        return ','.join(tokens)

    def deserialize(self, data: str) -> 'TreeNode':
        tokens = iter(data.split(','))
        def build():
            token = next(tokens)
            if token == '#':
                return None
            node = TreeNode(int(token))
            node.left = build()
            node.right = build()
            return node
        return build()
